import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"兌","description":"焦氏易林注 - 兌","frontmatter":{"title":"兌","description":"焦氏易林注 - 兌"},"headers":[],"relativePath":"classics/jiaoyilin/058.md","filePath":"classics/jiaoyilin/058.md"}'),l={name:"classics/jiaoyilin/058.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="兌" tabindex="-1">兌 <a class="header-anchor" href="#兌" aria-label="Permalink to “兌”">​</a></h1><h3 id="兌-1" tabindex="-1">兌 <a class="header-anchor" href="#兌-1" aria-label="Permalink to “兌”">​</a></h3><h3 id="兌之乾" tabindex="-1">兌之乾 <a class="header-anchor" href="#兌之乾" aria-label="Permalink to “兌之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>踐履危難，脫厄去患。入福喜門，見誨大君。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《震》之《家人》。厄去，宋元本作危去，汲古作去厄，依元本。</p><h3 id="兌之坤" tabindex="-1">兌之坤 <a class="header-anchor" href="#兌之坤" aria-label="Permalink to “兌之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>子鋤執麟，春秋作經。元聖將終，尼父悲心。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>經元，宋元本作元陰，茲依汲古訟之同人校。</p><h3 id="兌之屯" tabindex="-1">兌之屯 <a class="header-anchor" href="#兌之屯" aria-label="Permalink to “兌之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>夾河為婚，期至無船。搖心失望，不見所歡。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《小畜》。搖汲古作淫，非，依宋元本。</p><h3 id="兌之蒙" tabindex="-1">兌之蒙 <a class="header-anchor" href="#兌之蒙" aria-label="Permalink to “兌之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>天孫帝子，與日月處。光榮於世，福祿祉祉。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《解》之《臨》。祉祉，宋元本作繁祉，依元本。</p><h3 id="兌之需" tabindex="-1">兌之需 <a class="header-anchor" href="#兌之需" aria-label="Permalink to “兌之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>三羊爭雌，相隨奔馳。終日不食，精氣勞疲。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>羊、雌，依乾之大畜校，宋本、汲古羊作年，元本作人，雌皆作妻。</p><h3 id="兌之訟" tabindex="-1">兌之訟 <a class="header-anchor" href="#兌之訟" aria-label="Permalink to “兌之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>禹召諸侯，會稽南山。執玉萬國，天下康安。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>康安，宋元本作康寧，汲古作安寧，皆不協，依損之旅校。</p><h3 id="兌之師" tabindex="-1">兌之師 <a class="header-anchor" href="#兌之師" aria-label="Permalink to “兌之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>早霜晚雪，傷我禾麥。損功棄力，飢無所食。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《遯》。損，元本、汲古作捐，依宋本。</p><h3 id="兌之比" tabindex="-1">兌之比 <a class="header-anchor" href="#兌之比" aria-label="Permalink to “兌之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>嵩融持，杜伯荷弩。降觀下國，誅逐無道。夏商之季，失福逃走。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮為山，為，艮手，故曰嵩融持。翟雲升雲：《國語》：祝融降於崇山。崇即嵩字。按下文曰誅逐無道，其事必與杜伯相類，翟說非也。《墨子非攻下》雲：湯之時有神來告曰，夏德大亂，往攻之，予必使汝大堪之。予既受命於天，天命融隆火於夏之城。疑融隆即嵩融。又《國語》雲：夏之亡也以回祿，回祿仍火神也。是墨子說與林詞誅除無道夏商之季合，與《國語》亦合。惟《墨子》不言持，或焦氏別有所據，若其事則無疑也。且嵩融與融隆皆音近字轉。又按《楚辭》雲：&quot;吾令豐隆乘雲兮&quot;王逸註：雲師。《淮南子》雲：季春三月，豐隆乃出。許慎註：雷師。吳摯父先生雲，《墨子》之融隆即豐隆，依許註則雷師也。《墨子》所謂火其城，以雷火燒其城也。然則融隆為雷師而非祝融，尤與《國語》合。以《國語》&quot;夏之興也祝融降，其亡也以回祿&quot;，明回祿非祝融也。艮為弩、為負何。杜伯似用覆震象。艮為觀、為國，坤殺，故曰誅。伏離為夏，兌為商，艮為季，坤兇，故曰失福。《國語》杜伯射王於鎬，註：宣王殺杜伯，而非其罪，後王獵，杜伯起於道左，以朱弓矢射王中心而死。○夏，汲古訛憂，依宋元本。福，宋元本作勢，逃作外，茲依汲古。</p><h3 id="兌之小畜" tabindex="-1">兌之小畜 <a class="header-anchor" href="#兌之小畜" aria-label="Permalink to “兌之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>生有聖德，上配太極。皇靈建中，受我以福。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《需》。</p><h3 id="兌之履" tabindex="-1">兌之履 <a class="header-anchor" href="#兌之履" aria-label="Permalink to “兌之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>下田陸黍，萬華生齒。大雨霖集，波病潰腐。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>通《謙》。坤為下田，艮為陸，震為黍。兌為華、為齒，坤多，故曰萬華生齒。坤水，坎水，故曰大雨霖集。坎為波、為病，巽為腐。</p><h3 id="兌之泰" tabindex="-1">兌之泰 <a class="header-anchor" href="#兌之泰" aria-label="Permalink to “兌之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>子畏於匡，困厄陳蔡。明德不危，竟得免害。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《晉》。</p><h3 id="兌之否" tabindex="-1">兌之否 <a class="header-anchor" href="#兌之否" aria-label="Permalink to “兌之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>有兩赤鷂，從五隼噪。操矢無筈，趨釋爾射。扶伏聽命，不敢動搖。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>艮為鷂、為隼，乾為大赤，故曰赤鷂。坤數二，故曰兩。巽卦數五，故曰五隼。艮為矢，艮手為操。筈，矢未受弦處也。按：卦象兌應為筈，兌伏，故曰無筈。震為射，震覆，故曰趨釋爾射，言矢既無筈應，釋矢不射，而扶伏聽命也。巽為命，艮手在地，故曰扶伏。扶伏，匍匐也。《說文》伏地也。《詩大雅》誕實匍匐，《傳》以手行也。《前漢霍光傳》扶服叩頭。扶伏、扶服義皆同也。艮止，故不動。動亦有去聲，與命為韻。動搖，應作搖動。○黃丕烈雲俯當從《無妄》之《中孚》作扶，豈知前四句皆當依之，不止此一字也。鷂，各本皆作頭，隼噪作嶽遊，或作嶽來，三四句汲古作謠言無佑、趨爾之丘，宋元本同，惟丘作林。若依汲古搖與頭遊丘為韻，亦協，惟義皆不適，且爾趨等字皆仍舊。謠言無佑，無為矢之訛，佑為括之訛，以宋元本筈作括也，故全林皆依《無妄》之《中孚》校。鷂與噪韻，筈與射韻，命與動韻，且卦象皆符合。</p><h3 id="兌之同人" tabindex="-1">兌之同人 <a class="header-anchor" href="#兌之同人" aria-label="Permalink to “兌之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>當得自知，不逢兇災。衰者復興，終無禍來。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>離為災，乾福，故不逢，故無禍。○知，宋元本作如，依汲古。無禍，汲古作得福，依宋元本。</p><h3 id="兌之大有" tabindex="-1">兌之大有 <a class="header-anchor" href="#兌之大有" aria-label="Permalink to “兌之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>朽根刖樹，華葉落去。卒逢火焱，隨風僵僕。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《坎》。惟此用遇卦兌象須知。</p><h3 id="兌之謙" tabindex="-1">兌之謙 <a class="header-anchor" href="#兌之謙" aria-label="Permalink to “兌之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>葛生衍蔓，絺綌為願。家道篤厚，父兄悅喜。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>震為葛、為蕃鮮，故曰衍蔓。坤為帛、為絺綌、為願，艮為家、為篤厚，震為公，故曰父。為兄、為喜，《詩周南葛覃篇》為絺為綌。服之無斁。</p><h3 id="兌之豫" tabindex="-1">兌之豫 <a class="header-anchor" href="#兌之豫" aria-label="Permalink to “兌之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>東行求玉，反得弊石。名曰無直，字曰醜惡，眾所賤薄。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《否》。</p><h3 id="兌之隨" tabindex="-1">兌之隨 <a class="header-anchor" href="#兌之隨" aria-label="Permalink to “兌之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>瞻白用弦，駑孱恐怯。任力墮劣，如蝟見鵲。偃視恐伏，不敢拒格。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>互大坎，故曰恐怯，故曰蝟。震為鵲，巽伏，故曰偃。巽為弦、為白，然首句恐有訛字。○用，宋元本作因。按：兌為月，兌月上弦，白或為月之訛。</p><h3 id="兌之蠱" tabindex="-1">兌之蠱 <a class="header-anchor" href="#兌之蠱" aria-label="Permalink to “兌之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>瘡痍多病，宋公危殆。吳子巢門，隕命失所。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為節，故曰瘡痍。艮為宋，震為公，巽為病，正反巽，故曰多病、曰危殆。宋襄公戰泓傷股，震為吳、為子，艮為巢、為門，巽為命、為隕落，故曰隕命。詳《巽》之《鼎》。○隕，各本皆作無，依《小過》之《睽》校。</p><h3 id="兌之臨" tabindex="-1">兌之臨 <a class="header-anchor" href="#兌之臨" aria-label="Permalink to “兌之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>東山西嶽，會合俱食。百喜送從，以成恩福。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>伏艮為山嶽，震東，兌西，故曰東山西嶽。兌為食，坤為會、為百，震為喜福。○百喜，汲古作為吳，送從作從送，依宋元本。</p><h3 id="兌之觀" tabindex="-1">兌之觀 <a class="header-anchor" href="#兌之觀" aria-label="Permalink to “兌之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>舞非其處，失節多悔，不合我意。巽進退，故曰舞。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>舞在山上，故曰非其處。艮為節，坤為亡，故曰失節。坤為悔、為意。</p><h3 id="兌之噬嗑" tabindex="-1">兌之噬嗑 <a class="header-anchor" href="#兌之噬嗑" aria-label="Permalink to “兌之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>南循汝水，伐樹斬枝。過時不遇，惄如周飢。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離為南，互坎，故曰汝水。震為樹，二至四互艮，艮為刀劍，故曰斬枝。《詩周南》遵彼汝墳，伐其條枚；未見君子，惄如調飢。艮為時，坎為伏，故不遇。惄，思也，憂也。坎象也。離虛，故曰飢。周，《毛詩》作調，《傳》雲朝也。丁晏雲：周，《釋文》作輖，周即輖之省文。按：震為周、為旦，是焦詩與毛異文，猶韓詩惄作溺也。○第四句惄元本作，周作旦，依宋本、汲古。</p><h3 id="兌之賁" tabindex="-1">兌之賁 <a class="header-anchor" href="#兌之賁" aria-label="Permalink to “兌之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>公孫駕驪，載遊東齊。延陵說產，遺季紵衣。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《艮》之《未濟》。○季，宋元本作我，依汲古。</p><h3 id="兌之剝" tabindex="-1">兌之剝 <a class="header-anchor" href="#兌之剝" aria-label="Permalink to “兌之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>乘輿八百，以明文德。踐土葵丘，齊晉受福。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《同人》。</p><h3 id="兌之復" tabindex="-1">兌之復 <a class="header-anchor" href="#兌之復" aria-label="Permalink to “兌之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>雄處弱水，雌在海濱。別離將食，悲哀於心。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《同人》。</p><h3 id="兌之無妄" tabindex="-1">兌之無妄 <a class="header-anchor" href="#兌之無妄" aria-label="Permalink to “兌之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>結網得鮮，受福安坐，終無患禍。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽為繩，故曰結網。巽為魚，故曰得鮮。乾為福，艮為坐。</p><h3 id="兌之大畜" tabindex="-1">兌之大畜 <a class="header-anchor" href="#兌之大畜" aria-label="Permalink to “兌之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>秋南春北，隨時休息。處和履中，安無憂兇。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>兌為秋，震為春，乾南，坤北，艮為時，艮止，故曰休息。兌悅，故曰和。震足，故曰履。坤為憂兇，坤伏，故無。○安無，汲古作無有，依宋元本。</p><h3 id="兌之頤" tabindex="-1">兌之頤 <a class="header-anchor" href="#兌之頤" aria-label="Permalink to “兌之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>啟戶開門，巡狩釋冤。夏臺羑里，湯文悅喜。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>坤為門戶，震為啟、為巡狩，坤為憂、為冤，震解，故曰釋冤。艮為臺，納丙，故曰夏臺。坤為裡，震為帝，故曰湯文悅喜。○羑，宋元本作牖。</p><h3 id="兌之大過" tabindex="-1">兌之大過 <a class="header-anchor" href="#兌之大過" aria-label="Permalink to “兌之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>符左契右，相與合齒。乾坤利貞，乳生六子。長大成就，風言如母。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《未濟》。大過通頤。艮節震符，震為左，兌為右，故曰符左契右。兌為齒，正反兌，故曰合齒。大過為亥月卦，坤與乾相遇於亥，陰牝陽，故曰乾坤利貞。艮為乳，震為生，為子，乾數六，故曰六子。巽為風，震為言，巽亦為母，故曰如母。《坤上六》龍戰於野，其血玄黃。即林所言之義，詳《焦氏易詁》。</p><h3 id="兌之坎" tabindex="-1">兌之坎 <a class="header-anchor" href="#兌之坎" aria-label="Permalink to “兌之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>飢蠶作室，絲多亂緒，端不可得。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《同人》。</p><h3 id="兌之離" tabindex="-1">兌之離 <a class="header-anchor" href="#兌之離" aria-label="Permalink to “兌之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>東壁餘光，數暗不明。主母嫉妬，亂我事業。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《屯》。</p><h3 id="兌之鹹" tabindex="-1">兌之鹹 <a class="header-anchor" href="#兌之鹹" aria-label="Permalink to “兌之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>白茅縮酒，靈巫拜禱。神嗜飲食，使君壽考。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《坎》。縮，元本作醴，汲古作，依宋本。</p><h3 id="兌之恆" tabindex="-1">兌之恆 <a class="header-anchor" href="#兌之恆" aria-label="Permalink to “兌之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>範公陶朱，巧賈貨資。東之營丘，易字子皮。抱珠載金，多得利歸。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為蟲，故曰範。震為公，乾為大赤，伏艮火，故曰陶朱。巽為利、為商賈，故曰巧賈貨資。震為東，伏艮，故曰營丘。坤為字、艮為皮，震為子，坤艮皆伏，故曰易字子皮，言陶朱公范蠡後適齊，改名曰鴟夷子皮，隱居貿易也。事見《史記》。震為珠，艮為金，艮手，故曰抱珠。震車，故曰載金。巽為利，震為歸。○朱，宋元本作夷，依汲古。營，汲古訛榮，依宋元本。</p><h3 id="兌之遯" tabindex="-1">兌之遯 <a class="header-anchor" href="#兌之遯" aria-label="Permalink to “兌之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>三羖五牂，相隨俱行。迷入空澤，循谷直北。經涉六駁，為所傷賊。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《蒙》。汲古澤下多經涉虎廬，賊下多死於牙腹二句，依宋元本。</p><h3 id="兌之大壯" tabindex="-1">兌之大壯 <a class="header-anchor" href="#兌之大壯" aria-label="Permalink to “兌之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>雄鵠延頸，欲飛入關。雨師灑道，瀸我袍裘。車重難遷，侍者稽首。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>震為鵠、為飛，伏艮為關，兌為雨，震為道，故曰雨師灑道。乾為衣，故曰袍裘。坤為車、為重，艮止，故難遷。艮為斯役，故曰侍者。艮為首，艮止，故曰稽首。末二句皆伏象。○首，宋元本作上，依汲古。</p><h3 id="兌之晉" tabindex="-1">兌之晉 <a class="header-anchor" href="#兌之晉" aria-label="Permalink to “兌之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>中年蒙慶，今歲受福。必有所得，榮寵受祿。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>互坎為中，坤為年歲，艮為榮，伏乾為福祿。○寵，依宋元本，汲古無此句。局本寵作慶。</p><h3 id="兌之明夷" tabindex="-1">兌之明夷 <a class="header-anchor" href="#兌之明夷" aria-label="Permalink to “兌之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>祿如周公，建國洛東，父子俱封。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《革》之《明夷》。</p><h3 id="兌之家人" tabindex="-1">兌之家人 <a class="header-anchor" href="#兌之家人" aria-label="Permalink to “兌之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>安床厚褥，不得久宿。棄我嘉仯困於東國。投杼之憂，不成災福。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《睽》。災福，汲古作禍災，不韻，依宋元本。</p><h3 id="兌之睽" tabindex="-1">兌之睽 <a class="header-anchor" href="#兌之睽" aria-label="Permalink to “兌之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>蓄積有餘，糞土不居。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>汲古多利有所得四字，依宋元本。</p><h3 id="兌之蹇" tabindex="-1">兌之蹇 <a class="header-anchor" href="#兌之蹇" aria-label="Permalink to “兌之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>心願所喜，乃今逢時。得我利福，不離兵革。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>坎為心願，艮為時、為兵革。</p><h3 id="兌之解" tabindex="-1">兌之解 <a class="header-anchor" href="#兌之解" aria-label="Permalink to “兌之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>目不可合，憂來搔足。怵惕危懼，去其邦族。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《萃》之《睽》。</p><h3 id="兌之損" tabindex="-1">兌之損 <a class="header-anchor" href="#兌之損" aria-label="Permalink to “兌之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>福德之土，歡悅日喜。夷吾相桓，三歸為臣，賞流子孫。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為福德、為上、為歡悅，艮為桓。桓，木表也，言管仲相齊桓公也。艮為臺、為臣，故曰三歸為臣。震為歸，數三，三歸亦震象。《論語》曰管氏有三歸，官事不攝焉得儉，朱註：三歸，臺名，後儒不知朱註本《說苑》，頗訝與古註異，今易林以艮為三歸，是亦以三歸為臺也。</p><h3 id="兌之益" tabindex="-1">兌之益 <a class="header-anchor" href="#兌之益" aria-label="Permalink to “兌之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>夏姬附耳，心聽悅喜，利以博取。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>巽為夏，震為姬，伏兌為耳，坤為心，震為喜，巽為利。○末句汲古作利後博取，茲以字從宋元本。博，從汲古。</p><h3 id="兌之夬" tabindex="-1">兌之夬 <a class="header-anchor" href="#兌之夬" aria-label="Permalink to “兌之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>叔迎伯兄，遇巷在陽。君子季姬，並坐鼓簧。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>此用兌象。伏艮為叔，伏震為伯兄，艮震相對，故曰迎。艮為君子，兌為季姬，重兌，故曰並坐。震為鼓簧。○伯兄，宋元本、汲古皆作兄弟，依《鹹》之《震》校。巷，宋元本作恭，仍不愜，恐有訛字。《詩秦風》既見君子，並坐鼓簧。</p><h3 id="兌之姤" tabindex="-1">兌之姤 <a class="header-anchor" href="#兌之姤" aria-label="Permalink to “兌之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>徙巢去家，南遇白烏。東西受福，與喜相得。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>此仍用兌象。伏艮為巢、為家。伏震為南，艮為烏，互巽，故曰白烏。震為東、為喜福，兌為西。○烏，元本作鳥，非，依宋本。汲古烏與家為韻。家，音姑。</p><h3 id="兌之萃" tabindex="-1">兌之萃 <a class="header-anchor" href="#兌之萃" aria-label="Permalink to “兌之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>舜登大禹，石夷之野。徵詣王庭，拜治水土。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《中孚》。王庭，宋元本作玉闕，依汲古。</p><h3 id="兌之升" tabindex="-1">兌之升 <a class="header-anchor" href="#兌之升" aria-label="Permalink to “兌之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>江河淮海，天之都市。商人受福，國家富有。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>坤為江河淮海、為都，巽為市，伏乾，故曰天之都市。震為商人、為福，坤為國家、為富有。</p><h3 id="兌之困" tabindex="-1">兌之困 <a class="header-anchor" href="#兌之困" aria-label="Permalink to “兌之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>隱隱填填，火燒山根。不潤我鄰，獨不蒙恩。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《蹇》。填填，汲古作煩煩，不作下，依宋元本。</p><h3 id="兌之井" tabindex="-1">兌之井 <a class="header-anchor" href="#兌之井" aria-label="Permalink to “兌之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>闇昧不明，耳聾不聰。陷入深淵，滅頂憂兇。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《巽》之《小畜》。頂，元本作傾，依宋本、汲古。</p><h3 id="兌之革" tabindex="-1">兌之革 <a class="header-anchor" href="#兌之革" aria-label="Permalink to “兌之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴喈喈，天火降下。燔我館舍，災及妃後。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《晉》。嘻嘻，宋元、汲古本皆作喈喈。喈，音稽。嘻同喜，疑喈喈與嘻嘻通用。焦即作喈，不必定為訛字也。</p><h3 id="兌之鼎" tabindex="-1">兌之鼎 <a class="header-anchor" href="#兌之鼎" aria-label="Permalink to “兌之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>十雞百雛，常與母俱。抱雞捕虎，誰肯為侶。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《旅》之《夬》。雞與第四句皆依校，各本皆作雉，皆作誰敢難者，均非。</p><h3 id="兌之震" tabindex="-1">兌之震 <a class="header-anchor" href="#兌之震" aria-label="Permalink to “兌之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>營城洛邑，周公所作。世建三十，年厯八百。福佑盤結，堅固不落。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>詳《井》之《升》。盤結，宋元本作盟執，依汲古。</p><h3 id="兌之艮" tabindex="-1">兌之艮 <a class="header-anchor" href="#兌之艮" aria-label="Permalink to “兌之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>三人俱行，別離將食。一身五心，反覆迷惑。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《賁》。</p><h3 id="兌之漸" tabindex="-1">兌之漸 <a class="header-anchor" href="#兌之漸" aria-label="Permalink to “兌之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>三虎搏狼，力不相當。如鷹格雉，一擊破亡。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為虎狼，納丙，故曰三虎搏狼。艮為鷹，離為雉。格，敵也。《史記張儀傳》驅群羊攻猛虎，不格明矣，註：格，敵也。坎為破，艮為擊。○第三句元本作如雉鷹格，則格宜訓為鬬，《國語》谷洛鬬。韋昭曰：二水格雉鷹，格即雉，鷹鬬也，亦可從。擊，宋元本作發，依汲古。</p><h3 id="兌之歸妹" tabindex="-1">兌之歸妹 <a class="header-anchor" href="#兌之歸妹" aria-label="Permalink to “兌之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>養虎畜狼，還自賊傷。無事招禍，自取災殃。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>詳《井》之《蠱》。宋元、汲古下二句皆作年歲息長，疾君拜禱，雖危不兇，與上文意不屬，定為由他林竄入，故依《井》之《蠱》校。</p><h3 id="兌之豐" tabindex="-1">兌之豐 <a class="header-anchor" href="#兌之豐" aria-label="Permalink to “兌之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>後時失利，不得所欲。</p><h3 id="兌之旅" tabindex="-1">兌之旅 <a class="header-anchor" href="#兌之旅" aria-label="Permalink to “兌之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>雉兔之東，以野為場。見鷹驚走，死於谷口。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離為雉，伏震為兔、為東，艮為野、為場。兌為見，艮為鷹，伏震，故曰見鷹驚走。兌毀，故曰死。兌為口，艮為谷。○野場，宋元本作理傷，依汲古。驚，汲古作奔，依宋元本。</p><h3 id="兌之巽" tabindex="-1">兌之巽 <a class="header-anchor" href="#兌之巽" aria-label="Permalink to “兌之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>秋蛇向穴，不失其節。夫人薑氏，自齊復入。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《損》。</p><h3 id="兌之兌" tabindex="-1">兌之兌 <a class="header-anchor" href="#兌之兌" aria-label="Permalink to “兌之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>班馬還師，以息勞疲。役夫嘉喜，入戶見妻。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《觀》之《既濟》。役，宋元本作後，依汲古。</p><h3 id="兌之渙" tabindex="-1">兌之渙 <a class="header-anchor" href="#兌之渙" aria-label="Permalink to “兌之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>鳥鳴葭端，一呼三顛。搖動東西，危魂不安。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《復》之《井》。</p><h3 id="兌之節" tabindex="-1">兌之節 <a class="header-anchor" href="#兌之節" aria-label="Permalink to “兌之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>命夭不遂，死多鬼祟。妻子啼喑，早失其雄。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>伏巽為命，兌毀，故曰死。坎為鬼，兌為妻，震為子，兌口為啼。啼失聲曰喑。坎失，故曰啼喑。震為雄。○鬼，汲古作為，依宋元本。</p><h3 id="兌之中孚" tabindex="-1">兌之中孚 <a class="header-anchor" href="#兌之中孚" aria-label="Permalink to “兌之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>茆屋結席，崇我文德。三辰旗旗，家受其福。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>巽為茆，互艮，故曰茆屋。互震為席，巽為結，艮為崇、為我，震為德，故曰崇我文德。震為旗、為辰，數三，故曰三辰。艮為家，震為福，故曰家受其福。○其，汲古作行，依宋元本。</p><h3 id="兌之小過" tabindex="-1">兌之小過 <a class="header-anchor" href="#兌之小過" aria-label="Permalink to “兌之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>羅網四張，鳥無所翔。征伐困極，飢窮不食。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>巽為繩，故曰羅網。震為張，卦數四，故曰四張。艮為鳥，止於網下，故曰鳥無所翔。震為征伐，互大坎為勞，故曰困極。伏大離，離虛，故曰飢。兌為食，艮止，故不食。○四，汲古作一，所亦作一，茲依宋元本。</p><h3 id="兌之既濟" tabindex="-1">兌之既濟 <a class="header-anchor" href="#兌之既濟" aria-label="Permalink to “兌之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>天成地安，積石為山。潤洽萬裡，人賴其歡。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>乾坤爻皆當位，故曰天成地安。三半艮，故曰積石為山。坎為潤洽，半震為歡。○首句宋元本作天城地安，茲依汲古。汲古洽訛給。又按：此林似用兌象。</p><h3 id="兌之未濟" tabindex="-1">兌之未濟 <a class="header-anchor" href="#兌之未濟" aria-label="Permalink to “兌之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>銅人鐵柱，暴露勞苦。終月卒歲，無有休止。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>此用兌象。伏艮為銅鐵、為柱，伏坎為勞苦。艮為終、為時，故曰終月卒歲。艮為休止，艮伏，故曰無。</p>',320)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
